import{_ as e,c as l,o as r,aM as s}from"./chunks/framework.kKeYZnSg.js";const o="/fe-handbook/assets/ssg-md-flow.Bos5X7RL.jpg",x=JSON.parse('{"title":"Rspress","description":"","frontmatter":{},"headers":[],"relativePath":"build-tools/rstack/rspress/index.md","filePath":"build-tools/rstack/rspress/index.md","lastUpdated":1785481197000}'),a={name:"build-tools/rstack/rspress/index.md"};function n(d,t,i,c,g,f){return r(),l("div",null,t[0]||(t[0]=[s('<h1 id="rspress" tabindex="-1"><a href="https://rspress.rs/" target="_blank" rel="nofollow noopener noreferrer">Rspress</a> <a class="header-anchor" href="#rspress" aria-label="Permalink to &quot;[Rspress](https://rspress.rs/)&quot;">​</a></h1><blockquote><p>Rspress is a <strong>static site generator</strong> built with <strong>Rust</strong>, designed to be fast and efficient.</p></blockquote><h2 id="features" tabindex="-1">Features <a class="header-anchor" href="#features" aria-label="Permalink to &quot;Features&quot;">​</a></h2><ul><li>support for MDX</li><li>Built-in full-text search</li><li>AI-friendly</li></ul><h2 id="static-site-generation-to-markdown-ssg-md" tabindex="-1">Static Site Generation to Markdown (SSG-MD) <a class="header-anchor" href="#static-site-generation-to-markdown-ssg-md" aria-label="Permalink to &quot;Static Site Generation to Markdown (SSG-MD)&quot;">​</a></h2><blockquote><p>将你的页面渲染为 Markdown 文件，而非 HTML 文件，并生成 llms.txt 及 llms-full.txt 相关文件，便于大模型理解和使用你的技术文档。</p></blockquote><table tabindex="0"><thead><tr><th style="text-align:left;">类比项</th><th style="text-align:left;">SSG</th><th style="text-align:left;">SSG-MD</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>全称</strong></td><td style="text-align:left;">Static Site Generation</td><td style="text-align:left;">Static Site Generation to Markdown</td></tr><tr><td style="text-align:left;"><strong>优化目标</strong></td><td style="text-align:left;">SEO（搜索引擎优化）</td><td style="text-align:left;">GEO（生成式引擎优化）</td></tr><tr><td style="text-align:left;"><strong>面向对象</strong></td><td style="text-align:left;">搜索引擎爬虫</td><td style="text-align:left;">大语言模型 / 向量化检索系统</td></tr><tr><td style="text-align:left;"><strong>索引文件</strong></td><td style="text-align:left;"><a href="https://www.sitemaps.org/" target="_blank" rel="nofollow noopener noreferrer"><code>sitemap.xml</code></a></td><td style="text-align:left;"><a href="https://llmstxt.org/" target="_blank" rel="nofollow noopener noreferrer"><code>llms.txt</code></a></td></tr><tr><td style="text-align:left;"><strong>完整内容文件</strong></td><td style="text-align:left;">-</td><td style="text-align:left;"><code>llms-full.txt</code></td></tr><tr><td style="text-align:left;"><strong>核心实现</strong></td><td style="text-align:left;"><code>renderToString</code></td><td style="text-align:left;"><code>renderToMarkdownString</code></td></tr><tr><td style="text-align:left;"><strong>访问方式</strong></td><td style="text-align:left;"><code>/guide/start/introduction.html</code></td><td style="text-align:left;"><code>/guide/start/introduction.md</code></td></tr></tbody></table><h2 id="llms-txt" tabindex="-1">llms.txt <a class="header-anchor" href="#llms-txt" aria-label="Permalink to &quot;llms.txt&quot;">​</a></h2><blockquote><p><a href="https://llmstxt.org/" target="_blank" rel="nofollow noopener noreferrer"><code>llms.txt</code></a> 是一种新兴的标准化文件格式，放置于网站根目录，帮助大语言模型更好地理解和使用网站内容。</p><p>由于 LLM 的上下文窗口有限，无法处理整个网站的 HTML 内容，而将复杂的 HTML（包含导航、广告、JavaScript）转换为纯文本既困难又不精确。<code>llms.txt</code> 使用 Markdown 格式提供网站的结构化索引，包含页面 URL 及其内容描述，让 AI 能够快速定位和理解关键信息。</p><p>简单来说：</p><ul><li><code>sitemap.xml</code> → 给搜索引擎看的&quot;网站地图&quot;</li><li><code>llms.txt</code> → 给 AI 看的&quot;文档目录&quot;</li></ul></blockquote><p><img src="'+o+'" alt="ssg-md-flow"></p>',10)]))}const u=e(a,[["render",n]]);export{x as __pageData,u as default};
